def transform(grid):
    n = len(grid)
    sep = next(i for i, v in enumerate(grid[0]) if v != 0)
    tile = sep
    # motif is the nonzero pattern in the occupied tile of the second band
    motif = [[int(grid[tile+1+r][2*tile+2+c] != 0) for c in range(tile)] for r in range(tile)]
    # Identify band colors from the isolated 2x2 samples at first tile column.
    colors = []
    for band in range(0,n,tile+1):
        vals = [grid[band+r][1+c] for r in range(tile) for c in range(2) if grid[band+r][1+c] != 0]
        colors.append(vals[0] if vals else 0)
    out = [[0]*n for _ in range(n)]
    for r in range(n):
        for c in range(n):
            if r % (tile+1) == tile or c % (tile+1) == tile:
                out[r][c] = grid[r][c]
            else:
                band = r // (tile+1)
                if motif[r%(tile+1)][c%(tile+1)]:
                    out[r][c] = colors[band]
    return out
